const normalize=(s:string)=>String(s||'').normalize('NFKC').toLocaleLowerCase().replace(/[\u064b-\u065f\u0670\u0640]/g,'').replace(/\s+/g,' ').trim();
export const readingChallengeBooks:ReadingBook[]=definitions.flatMap(entry=>{
  const book=bookData.find(b=>normalize(b.title)===normalize(entry.title)&&b.language.toLowerCase()===entry.locale);
  // Never crash the entire protected application because one shelf entry was
  // reclassified or removed. Keep the remaining verified book challenges live.
  if(!book || entry.qs.length<5){
    console.warn('Reading challenge entry needs catalog review:',entry.key);
    return [];
  }
  return [{key:entry.key,role:entry.role as ReadingRole,locale:entry.locale as ReadingLocale,
    sourceUrl:entry.sourceUrl,sourceLabel:entry.sourceLabel,book,
    questions:entry.qs.map((q,i)=>({id:entry.key+'-'+(i+1),prompt:q[0],answers:[q[1],q[2],q[3]] as [string,string,string],correct:0 as const,reference:q[4]}))}];
});
export const getRoleReadingBooks=(role:ReadingRole,locale:ReadingLocale)=>
  readingChallengeBooks.filter(entry=>entry.role===role&&entry.locale===locale);
export const shuffleReading=<T,>(values:readonly T[],random:()=>number=Math.random):T[]=>{
 const result=[...values];
 for(let i=result.length-1;i>0;i--){
  const index=Math.floor(random()*(i+1));[result[i],result[index]]=[result[index],result[i]];
 }
 return result;
};
